47	func (c *Codex) IsTransientError(out Output, err error) bool {
48		if err == nil {
49			return false
50		}
51		if errors.Is(err, context.DeadlineExceeded) {
52			return true
53		}
54		combined := out.Stdout + out.Stderr
55		for _, p := range []string{"overloaded", "rate limit", "rate_limit", "503", "529", "ECONNRESET", "ETIMEDOUT"} {
56			if strings.Contains(combined, p) {
57				return true
58			}
59		}
60		return false
61	}
