85	func (c *Codex) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
86		cfg := &runConfig{}
87		for _, o := range opts {
88			o(cfg)
89		}
90	
91		timeout := 60 * time.Second
92		if cfg.PromptTimeout > 0 {
93			timeout = cfg.PromptTimeout
94		}
95		promptCtx, cancel := context.WithTimeout(ctx, timeout)
96		defer cancel()
97	
98		home, cleanup, err := codexHome()
99		if err != nil {
100			return Output{}, fmt.Errorf("create codex home: %w", err)
101		}
102		defer cleanup()
103	
104		absDir, err := filepath.Abs(dir)
105		if err != nil {
106			absDir = dir
107		}
108		if err := seedCodexHome(home, absDir); err != nil {
109			return Output{}, fmt.Errorf("seed codex home: %w", err)
110		}
111	
112		args := []string{"exec", "--dangerously-bypass-approvals-and-sandbox"}
113		if cfg.Model != "" {
114			args = append(args, "-m", cfg.Model)
115		}
116		args = append(args, prompt)
117	
118		env := append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME"),
119			"CODEX_HOME="+home,
120		)
121	
122		cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
123		cmd.Dir = dir
124		cmd.Stdin = nil
125		cmd.Env = env
126		setupProcessGroup(cmd)
127		cmd.WaitDelay = 5 * time.Second
128	
129		var stdout, stderr strings.Builder
130		cmd.Stdout = &stdout
131		cmd.Stderr = &stderr
132	
133		err = cmd.Run()
134		exitCode := 0
135		if err != nil {
136			exitErr := &exec.ExitError{}
137			if errors.As(err, &exitErr) {
138				exitCode = exitErr.ExitCode()
139			} else {
140				exitCode = -1
141			}
142			if promptCtx.Err() == context.DeadlineExceeded {
143				err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
144			}
145		}
146	
147		return Output{
148			Command:  c.Binary() + " " + strings.Join(args[:len(args)-1], " ") + " " + fmt.Sprintf("%q", prompt),
149			Stdout:   stdout.String(),
150			Stderr:   stderr.String(),
151			ExitCode: exitCode,
152		}, err
153	}
