155	func (c *Codex) StartSession(ctx context.Context, dir string) (Session, error) {
156		name := fmt.Sprintf("codex-test-%d", time.Now().UnixNano())
157	
158		home, cleanup, err := codexHome()
159		if err != nil {
160			return nil, fmt.Errorf("create codex home: %w", err)
161		}
162	
163		absDir, err := filepath.Abs(dir)
164		if err != nil {
165			absDir = dir
166		}
167		if err := seedCodexHome(home, absDir); err != nil {
168			cleanup()
169			return nil, fmt.Errorf("seed codex home: %w", err)
170		}
171	
172		s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox")
173		if err != nil {
174			cleanup()
175			return nil, err
176		}
177		s.OnClose(cleanup)
178	
179		// Dismiss startup dialogs (model upgrade prompts, etc.) until we reach
180		// the input prompt. Similar to Claude's startup dialog handling.
181		for range 5 {
182			content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
183			if waitErr != nil {
184				_ = s.Close()
185				return nil, fmt.Errorf("waiting for codex prompt: %w", waitErr)
186			}
187			if !strings.Contains(content, "press enter to confirm") &&
188				!strings.Contains(content, "Use ↑/↓ to move") {
189				break
190			}
191			_ = s.SendKeys("Enter")
192			time.Sleep(500 * time.Millisecond)
193		}
194	
195		return &CodexSession{TmuxSession: s, home: home}, nil
196	}
197	
198	func (c *Codex) ResumeSession(ctx context.Context, dir, home, sessionID string) (Session, error) {
199		_ = ctx
200		name := fmt.Sprintf("codex-resume-%d", time.Now().UnixNano())
201	
202		s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox", "resume", sessionID)
203		if err != nil {
204			return nil, err
205		}
206	
207		// Dismiss any startup prompts until the input prompt appears.
208		for range 5 {
209			content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
210			if waitErr != nil {
211				_ = s.Close()
212				return nil, fmt.Errorf("waiting for codex resumed prompt: %w", waitErr)
213			}
214			if !strings.Contains(content, "press enter to confirm") &&
215				!strings.Contains(content, "Use ↑/↓ to move") {
216				break
217			}
218			_ = s.SendKeys("Enter")
219			time.Sleep(500 * time.Millisecond)
220		}
221	
222		return &CodexSession{TmuxSession: s, home: home}, nil
223	}
224	
225	func (c *Codex) startTmuxSession(name, dir, home string, args ...string) (*TmuxSession, error) {
226		tmuxArgs := append([]string{"CODEX_HOME=" + home, "HOME=" + os.Getenv("HOME"), "TERM=" + os.Getenv("TERM")}, args...)
227		return NewTmuxSession(name, dir, []string{"CODEX_HOME", "ENTIRE_TEST_TTY"}, "env", tmuxArgs...)
228	}
